export type ExcelLevel = "principiante" | "intermedio" | "avanzado";
export type ExcelLessonType = "reading" | "sheet" | "quiz";
export type ExcelCellMap = Record<string, string>;
export type ExcelValueMap = Record<string, string | number | boolean | null>;
export type ExcelCheck = { desc: string; test: (cells: ExcelCellMap, values: ExcelValueMap) => boolean };
export type ExcelQuestion = { q: string; options: string[]; correct: number; explain: string };
export type ExcelLesson = {
  id: string; type: ExcelLessonType; icon: string; xp: number; minutes: number; title: string; desc: string;
  level: ExcelLevel; objectives: string[]; dax: { hint: string; explain: string; example: string };
  content?: string; keyPoints?: string[]; prompt?: string; initCells?: ExcelCellMap;
  checks?: ExcelCheck[]; solution?: ExcelCellMap; questions?: ExcelQuestion[];
};
export type ExcelModule = { id: string; title: string; minutes: number; goal: string; level: ExcelLevel; lessons: ExcelLesson[] };

type ReadingSpec = { title: string; desc: string; formula: string; keyPoints: [string, string, string]; note: string; tip: string; analogy: string };
type SheetSpec = { title: string; desc: string; prompt: string; cells: ExcelCellMap; formulas: string[]; solution: ExcelCellMap; results: Array<[string, number | string]>; functionName?: string; formulaPattern?: string; objectives: [string, string, string] };
type ModuleSpec = { title: string; goal: string; level: ExcelLevel; readings: ReadingSpec[]; sheets: SheetSpec[]; quiz: ExcelQuestion[] };

