export const EXCEL_MODULE_ICONS = ["📊", "🎯", "🔢", "🔍", "🧮", "📈", "🗂️", "⚡", "🧠", "🔎", "📉", "⚙️", "📋", "🤖", "🚀"];

function makeReading(spec: ReadingSpec, module: ModuleSpec, moduleIndex: number, lessonIndex: number): ExcelLesson {
  const content = `<p>${spec.desc} ${module.goal}</p><h3>Una analogía cotidiana</h3><p>${spec.analogy}</p><h3>Observa la fórmula</h3><pre>${spec.formula}</pre><ul>${spec.keyPoints.map((point) => `<li>${point}</li>`).join("")}</ul><div class="note"><b>Atención:</b> ${spec.note}</div><div class="tip"><b>Buena práctica:</b> ${spec.tip}</div>`;
  return { id: `m${moduleIndex + 1}l${lessonIndex + 1}`, type: "reading", icon: "📖", xp: 20, minutes: 10, title: spec.title, desc: spec.desc, level: module.level, objectives: ["Explicar el concepto con tus palabras.", "Interpretar la fórmula de ejemplo.", "Relacionar la técnica con una decisión real."], dax: { hint: `Antes de escribir la fórmula de ${spec.title.toLowerCase()}, identifica los datos de entrada y el resultado esperado.`, explain: spec.analogy, example: "=SUMA(12;18)" }, content, keyPoints: [...spec.keyPoints] };
}

function makeSheet(spec: SheetSpec, module: ModuleSpec, moduleIndex: number, lessonIndex: number): ExcelLesson {
  const checks: ExcelCheck[] = [
    ...spec.formulas.map((ref) => ({ desc: `${ref} contiene una fórmula, no un resultado fijo.`, test: (cells: ExcelCellMap) => typeof cells[ref] === "string" && cells[ref].startsWith("=") })),
    { desc: "Los datos iniciales y etiquetas están completos.", test: (cells: ExcelCellMap) => Object.entries(spec.cells).every(([ref, value]) => String(cells[ref] ?? "").trim().toLowerCase() === value.trim().toLowerCase()) },
    ...spec.results.map(([ref, expected]) => ({ desc: `${ref} calcula ${expected}.`, test: (_cells: ExcelCellMap, values: ExcelValueMap) => typeof expected === "number" ? typeof values[ref] === "number" && Math.abs(Number(values[ref]) - expected) < 0.01 : String(values[ref] ?? "") === expected })),
    ...(spec.functionName ? [{ desc: `La fórmula usa ${spec.functionName}.`, test: (cells: ExcelCellMap) => spec.formulas.some((ref) => (cells[ref] ?? "").toLocaleUpperCase().includes(spec.functionName!.toLocaleUpperCase())) }] : []),
    ...(spec.formulaPattern ? [{ desc: "La fórmula usa la resta entre las celdas de fecha indicadas.", test: (cells: ExcelCellMap) => spec.formulas.some((ref) => new RegExp(spec.formulaPattern!, "i").test(cells[ref] ?? "")) }] : []),
  ];
  const lastModule = moduleIndex === 14;
  return { id: `m${moduleIndex + 1}l${lessonIndex + 1}`, type: "sheet", icon: lastModule ? "🚀" : "💻", xp: lastModule ? 150 : module.level === "principiante" ? 50 : 60, minutes: lastModule ? 35 : module.level === "principiante" ? 18 : 20, title: spec.title, desc: spec.desc, level: module.level, objectives: [...spec.objectives], dax: { hint: "Empieza por completar las entradas; después escribe la fórmula usando referencias y revisa el valor calculado.", explain: "La hoja se comporta como un tablero de control: al cambiar una entrada, las fórmulas deben actualizar el resultado.", example: "=MAX(12;18)" }, prompt: `<p>${spec.prompt}</p><p><strong>Criterio:</strong> los resultados deben salir de fórmulas; escribirlos manualmente no supera la práctica.</p>`, initCells: {}, checks, solution: { ...spec.cells, ...spec.solution } };
}

function makeQuiz(questions: ExcelQuestion[], module: ModuleSpec, moduleIndex: number, lessonIndex: number): ExcelLesson {
  return { id: `m${moduleIndex + 1}l${lessonIndex + 1}`, type: "quiz", icon: "📝", xp: moduleIndex === 14 ? 100 : 60, minutes: moduleIndex === 14 ? 15 : 10, title: moduleIndex === 14 ? "Evaluación final del curso" : `Desafío: ${module.title}`, desc: "Analiza resultados y elige un método adecuado para el caso.", level: module.level, objectives: ["Interpretar una fórmula o resultado.", "Detectar un error frecuente.", "Elegir una estrategia adecuada al caso."], dax: { hint: "Lee todos los argumentos y determina qué conjunto de datos modifica cada uno.", explain: "Como una receta, el orden y la función de cada ingrediente determinan el resultado.", example: "=REDONDEAR(12.345;1)" }, questions };
}

export const EXCEL_CURRICULUM: ExcelModule[] = specs.map((module, moduleIndex) => {
  const lessons: ExcelLesson[] = [];
  module.readings.forEach((reading) => lessons.push(makeReading(reading, module, moduleIndex, lessons.length)));
  module.sheets.forEach((sheet) => lessons.push(makeSheet(sheet, module, moduleIndex, lessons.length)));
  lessons.push(makeQuiz(module.quiz, module, moduleIndex, lessons.length));
  return { id: `m${moduleIndex + 1}`, title: module.title, level: module.level, goal: module.goal, minutes: lessons.reduce((sum, lesson) => sum + lesson.minutes, 0), lessons };
});

export function validateExcelCurriculum() {
  const readings = [3, 2, 3, 3, 3, 3, 3, 3, 3, 3, 2, 2, 3, 3, 2];
  const sheets = [1, 1, 2, 2, 2, 1, 1, 0, 0, 1, 0, 0, 0, 0, 1];
  if (EXCEL_CURRICULUM.length !== 15 || EXCEL_MODULE_ICONS.length !== 15) throw new Error("El curso Excel debe tener 15 módulos e iconos.");
  EXCEL_CURRICULUM.forEach((module, index) => {
    const expectedLevel = index < 5 ? "principiante" : index < 10 ? "intermedio" : "avanzado";
    const moduleWords = module.title.trim().split(/\s+/).length;
    if (module.id !== `m${index + 1}` || moduleWords < 3 || moduleWords > 7 || module.level !== expectedLevel || module.lessons.filter((lesson) => lesson.type === "reading").length !== readings[index] || module.lessons.filter((lesson) => lesson.type === "sheet").length !== sheets[index] || module.lessons.filter((lesson) => lesson.type === "quiz").length !== 1) throw new Error(`El módulo ${module.id} de Excel incumple el esquema solicitado.`);
    if (index >= 10 && index < 14 && module.lessons.some((lesson) => lesson.type === "sheet")) throw new Error("Los módulos 11 a 14 no deben contener laboratorios de hoja.");
    module.lessons.forEach((lesson, lessonIndex) => {
      if (lesson.id !== `m${index + 1}l${lessonIndex + 1}` || lesson.title.trim().split(/\s+/).length > 6 || lesson.level !== module.level || !lesson.dax.hint || !lesson.dax.explain || !lesson.dax.example || lesson.objectives.length < 3) throw new Error(`La actividad ${lesson.id} está incompleta.`);
      if (lesson.type === "reading" && (lesson.xp !== 20 || lesson.minutes < 8 || lesson.minutes > 12)) throw new Error(`La lectura ${lesson.id} incumple el XP o duración acordados.`);
      if (lesson.type === "sheet" && (!lesson.checks?.length || !lesson.solution || Object.keys(lesson.initCells ?? {}).length || !lesson.checks.some((check) => check.desc.toLowerCase().includes("fórmula")))) throw new Error(`El laboratorio ${lesson.id} debe iniciar vacío y comprobar una fórmula real.`);
      if (lesson.type === "sheet" && (index === 14 ? lesson.xp !== 150 || lesson.minutes !== 35 : module.level === "principiante" ? lesson.xp !== 50 || lesson.minutes < 15 || lesson.minutes > 20 : lesson.xp !== 60 || lesson.minutes < 18 || lesson.minutes > 22)) throw new Error(`El laboratorio ${lesson.id} incumple el XP o duración acordados.`);
      if (lesson.type === "sheet") {
        const values = calculateExcelSheet(lesson.solution ?? {});
        const failedChecks = lesson.checks?.filter((check) => !check.test(lesson.solution ?? {}, values)).map((check) => check.desc) ?? [];
        if (failedChecks.length) throw new Error(`La solución del laboratorio ${lesson.id} no supera: ${failedChecks.join("; ")}. Valores calculados: ${JSON.stringify(values)}.`);
      }
      if (lesson.type === "quiz" && (lesson.xp !== (index === 14 ? 100 : 60) || lesson.minutes !== (index === 14 ? 15 : 10) || lesson.questions?.some((question) => question.options.length !== 4 || question.correct < 0 || question.correct >= question.options.length))) throw new Error(`El quiz ${lesson.id} tiene opciones, XP o duración inválidos.`);
    });
  });
}

